Ответь ровно одним словом: OK
import subprocess,time,json,os
cmd=['opencode','run','--standalone','--archived','--agent','build','--model','opencode-go/hungerg-free','--format','json','Ответь ровно одним словом: OK']
t=time.monotonic()
try:
 p=subprocess.run(cmd,capture_output=True,text=True,timeout=90,cwd='/tmp/opencode')
 out={'rc':p.returncode,'elapsed_s':round(time.monotonic()-t,2),'stdout_bytes':len(p.stdout),'stderr_bytes':len(p.stderr)}
 text=(p.stdout+'\n'+p.stderr)
 for needle in ('Timed out waiting for response data','Timed out waiting for response headers','ECONNRESET','Free usage limit reached','Retry due','error'):
  if needle.lower() in text.lower(): out.setdefault('signals',[]).append(needle)
 print(json.dumps(out,ensure_ascii=False))
 open('/tmp/opencode/hungerg-probe-output.txt','w').write(text)
except subprocess.TimeoutExpired as e:
 print(json.dumps({'timeout':True,'elapsed_s':round(time.monotonic()-t,2)},ensure_ascii=False))

